codes = ['A12', 'B7', 'X9', 'C3']

for code in codes:
    if len(code) == 2 and code[0].isalpha():
        print('accepted:', code)
        break
    print('rejected:', code)
else:
    print('no valid code found')

n = 5
while n > 0:
    if n == 3:
        n -= 1
        continue
    print('count', n)
    n -= 1
